procedure BubbleSortRecursive(var arr: array of integer; n: integer);
begin
  if n = 1 then
    exit;

  for var i := 0 to n - 2 do
  begin
    comparisonCount += 1;
    if arr[i] > arr[i + 1] then
    begin
      var tempVal := arr[i];
      arr[i] := arr[i + 1];
      arr[i + 1] := tempVal;
      swapCount += 1;
    end;
  end;

  BubbleSortRecursive(arr, n - 1);
end;

