function CountOccurrences(inputText, searchPattern: string): integer;
begin
  var occurrences := 0;
  var patternLength := searchPattern.Length;

  for var i := 0 to inputText.Length - patternLength do
  begin
    var match := true;

    for var j := 0 to patternLength - 1 do
    begin
      if inputText[i + j] <> searchPattern[j] then
      begin
        match := false;
        break;
      end;
    end;

    if match then
      occurrences += 1;
  end;

  Result := occurrences;
end;

