procedure QuickSort(var arr: array of integer; low, high: integer);
begin
  if low < high then
  begin
    var pivotIndex := Partition(arr, low, high);
    QuickSort(arr, low, pivotIndex - 1);
    QuickSort(arr, pivotIndex + 1, high);
  end;
end;

function Partition(var arr: array of integer; low, high: integer): integer;
begin
  var pivot := arr[high];
  var i := low - 1;

  for var j := low to high - 1 do
  begin
    if arr[j] <= pivot then
    begin
      i += 1;
      Swap(arr, i, j);
    end;
  end;

  Swap(arr, i + 1, high);
  Result := i + 1;
end;

procedure Swap(var arr: array of integer; index1, index2: integer);
begin
  var temp := arr[index1];
  arr[index1] := arr[index2];
  arr[index2] := temp;
end;

