function Partition(var arr: array of integer; low, high: integer): integer;
begin
  var pivot := arr[high];
  var i := low - 1;

  for var j := low to high - 1 do
  begin
    if arr[j] >= pivot then
    begin
      i += 1;
      Swap(arr, i, j);
    end;
  end;

  Swap(arr, i + 1, high);
  Result := i + 1;
end;

